@layer moduix.components {
  .root {
    --_checkbox-size: var(--moduix-spacing-5);
    --_checkbox-icon-size: var(--moduix-spacing-3);

    display: inline-flex;
    align-items: center;
    gap: var(--moduix-checkbox-gap, var(--moduix-spacing-2));
    vertical-align: middle;
    color: var(--moduix-color-foreground);
    cursor: pointer;

    &[data-disabled],
    &[data-readonly] {
      cursor: default;
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }

    &[data-size='xs'] {
      --_checkbox-size: var(--moduix-spacing-3-5);
      --_checkbox-icon-size: var(--moduix-spacing-2);
    }

    &[data-size='sm'] {
      --_checkbox-size: var(--moduix-spacing-4);
      --_checkbox-icon-size: var(--moduix-spacing-2-5);
    }

    &[data-size='lg'] {
      --_checkbox-size: var(--moduix-size-xs);
      --_checkbox-icon-size: var(--moduix-spacing-3-5);
    }

    &[data-size='xl'] {
      --_checkbox-size: var(--moduix-spacing-7);
      --_checkbox-icon-size: var(--moduix-spacing-4);
    }
  }

  .control {
    box-sizing: border-box;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: var(--moduix-checkbox-size, var(--_checkbox-size));
    height: var(--moduix-checkbox-size, var(--_checkbox-size));
    border: var(--moduix-border-width-sm) solid
      var(--moduix-checkbox-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-checkbox-radius, var(--moduix-radius-xs));
    background-color: var(--moduix-checkbox-bg, var(--moduix-color-background));
    color: var(--moduix-checkbox-color, var(--moduix-color-primary-foreground));
    user-select: none;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &[data-state='checked'],
    &[data-state='indeterminate'] {
      border-color: var(--moduix-checkbox-bg-checked, var(--moduix-color-primary));
      background-color: var(--moduix-checkbox-bg-checked, var(--moduix-color-primary));
    }

    &[data-focus-visible] {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
      color: var(--moduix-color-destructive-foreground);
      outline-color: var(--moduix-color-destructive);

      &[data-state='checked'],
      &[data-state='indeterminate'] {
        background-color: var(--moduix-color-destructive);
      }
    }

    @media (hover: hover) {
      &[data-state='unchecked'][data-hover]:not([data-readonly], [data-disabled]) {
        background-color: var(--moduix-color-accent);
      }
    }
  }

  .indicator {
    display: inline-flex;
    width: var(--moduix-checkbox-icon-size, var(--_checkbox-icon-size));
    height: var(--moduix-checkbox-icon-size, var(--_checkbox-icon-size));

    & > svg {
      width: 100%;
      height: 100%;
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .group {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-2);
  }
}

export interface CheckboxGroupEmits {
  valueChange: (value: string[]) => void;
  'update:modelValue': (value: string[]) => void;
}

import {
  CheckboxContext,
  CheckboxHiddenInput,
  useCheckbox,
  useCheckboxContext,
  useCheckboxGroup,
  useCheckboxGroupContext,
} from '@ark-ui/vue/checkbox';
import Checkbox from './Checkbox.vue';
import CheckboxControl from './CheckboxControl.vue';
import CheckboxGroup from './CheckboxGroup.vue';
import CheckboxIndicator from './CheckboxIndicator.vue';
import CheckboxLabel from './CheckboxLabel.vue';
import CheckboxRootProvider from './CheckboxRootProvider.vue';

export {
  Checkbox,
  CheckboxContext,
  CheckboxControl,
  CheckboxGroup,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxRootProvider,
  useCheckbox,
  useCheckboxContext,
  useCheckboxGroup,
  useCheckboxGroupContext,
};

export type {
  CheckboxContextProps,
  CheckboxControlProps,
  CheckboxGroupProps,
  CheckboxHiddenInputProps,
  CheckboxIndicatorProps,
  CheckboxLabelProps,
  CheckboxRootEmits,
  UseCheckboxContext,
  UseCheckboxGroupContext,
  UseCheckboxGroupProps,
  UseCheckboxGroupReturn,
  UseCheckboxProps,
  UseCheckboxReturn,
} from '@ark-ui/vue/checkbox';

export type { CheckboxSize, Props as CheckboxRootProps } from './Checkbox.vue';
export type { Props as CheckboxRootProviderProps } from './CheckboxRootProvider.vue';
